            new GuideArticle("victory-overview", "Победа", "Пять путей к победе", "Каждая партия допускает развитие разными способами.",
                "Победа не присуждается за одно лишь количество захваченных клеток. Откройте вкладку «Победа»: там указаны требования, текущее значение и доступность действий. Качество жизни проверяет устойчивость населения и городских служб; научный путь требует поздних открытий и проекта; культурный — объектов, престижа и фестиваля; дипломатический — маршрутов, общего кризиса и поддержки коалиции.\n\n" +
                "Если никто не завершит активный путь, в конце выбранного темпа сравнивается наследие цивилизаций. Можно стремиться к одному условию или гибко развивать население, города, науку, культуру, торговлю и репутацию одновременно.", "победа условие пути качество жизни наука культура дипломатия наследие"),
            new GuideArticle("victory-quality", "Победа", "Победа через качество жизни", "Устойчивые города должны несколько ходов подряд обеспечивать достойную жизнь.",
                "Нужно иметь не менее четырёх городов, достаточное качество жизни минимум у 80% населения, здоровье и безопасность не ниже порога в каждом городе, небольшой разрыв между городами и отсутствие затяжного дефицита. Условия должны сохраняться пять ходов подряд.\n\n" +
                "Вкладка «Победа» показывает индекс, подходящую долю населения, разброс городов и текущую серию спокойных ходов. Слабейший город часто важнее столицы: расширяйте службы, лечите нехватку еды и удерживайте налоги на приемлемом уровне. Начните подготовку заранее — новые города и службы требуют времени.", "победа качество благополучие индекс города здоровье безопасность доверие"),
            new GuideArticle("victory-science", "Победа", "Научная победа", "Поздние технологии открывают проект, который нужно поддерживать несколько ходов.",
                "Для прорыва нужны ключевые технологии «Вычислительные сети» и «Открытая наука», университеты в разных городах, академия, запас знаний и влияния. Затем начните проект в городе с доступным производством. Требуется несколько последовательных ходов проекта и устойчивый выпуск знаний.\n\n" +
                "Панель победы показывает число университетов, академий, прогресс проекта и последние значения выпуска знаний. Если наука падает, проверьте назначение исследователей, финансирование школ и состояние экономики. Запустите программу только в городе, который сможет закончить её без смены проекта.", "научная победа университет академия вычислительные сети открытая наука проект"),
            new GuideArticle("victory-culture", "Победа", "Культурная победа", "Культурное влияние создаётся в разных городах и закрепляется совместным фестивалем.",
                "Постройте культурный дом, архив и Дом обмена в трёх разных городах, накопите престиж и обеспечьте достаточное культурное влияние и казну. Когда условия выполнены, проведите фестиваль. Его нужно поддерживать два хода, поэтому не переводите город на другой проект и сохраните ресурсы.\n\n" +
                "Художники, культурные здания, открытая пресса, договоры и обмены помогают развивать престиж и влияние. На вкладке «Победа» видны количество объектов, престиж, влияние в соседних цивилизациях и стадия фестиваля.", "культурная победа культура престиж художники фестиваль культурный дом архив"),
            new GuideArticle("victory-diplomacy", "Победа", "Дипломатическая победа", "Международная ассамблея опирается на реальные связи и совместные действия.",
                "Исследуйте Международную ассамблею, постройте её и свяжите город маршрутами с двумя другими цивилизациями. Нужны общий разрешённый кризис, участие нескольких сторон, достаточное число голосов и вклад влияния. Затем создайте коалицию и удержите её установленное число ходов.\n\n" +
                "Отношения и доверие важны: соседи не обязаны поддерживать игрока, который угрожал им войной или разрушал торговлю. Стройте маршруты заранее, участвуйте в кризисах и следите за голосами на вкладке «Победа». Это совместный путь — изолированная развитая столица не выполнит его условия.", "дипломатическая победа ассамблея маршрут кризис коалиция голоса голосование"),
            new GuideArticle("victory-heritage", "Победа", "Победа через наследие", "В конце кампании сравниваются достижения всей цивилизации.",
                "Если к пределу кампании никто не завершил активный путь, сравнивается счёт наследия. Он учитывает население, качество городов, изученные технологии, культуру, дипломатические связи и репутацию; ущерб и цена войны ухудшают результат. Экран победы и вкладка «Победа» показывают очки и главные источники прогресса.\n\n" +
                "Длинный мирный план обычно выгоден: он сохраняет жителей и торговлю, помогает изучать технологии и улучшать города. Не откладывайте развитие до последних ходов — у культурных, научных и дипломатических проектов есть собственные сроки.", "наследие итоговый счёт финал кампания очки население технологии репутация"),
            new GuideArticle("ai", "Мир и события", "Как ведут себя соперники", "У цивилизаций разные долгосрочные планы, но они реагируют на угрозы и возможности.",
                "У каждого соперника есть характер и стратегический курс: например, наука, торговля, культура, расширение, качество жизни или безопасность. План удерживается несколько ходов и затем может измениться, если соперник отстал, столкнулся с голодом или войной либо увидел выгодный путь. Сильные соперники специализируются по характеру: учёный торопит научный проект, торговец строит международные связи, а стратег безопасности стремится к благополучию городов. Если в городе идёт строительство, жители переключаются на производство; голод и серьёзный долг временно меняют этот приоритет.\n\n" +
                "В обзоре мира рядом с курсом видны его оценка и ближайшая альтернатива. Оценка складывается из специализации, пути победы, учреждений и текущих проблем; война, риск голода и долг могут поднять срочный приоритет.\n\n" +
                "Сложность влияет на экономику и темп планирования. На сильном уровне соперники получают 12,5% выпуска и исследуют на 5% быстрее; на Испытании — 30% выпуска и на 10% быстрее. У них также выше стартовая административная ёмкость: на одну единицу на сильном уровне и на две на Испытании. Спокойная сложность даёт им на 5% меньше выпуска и помогает догонять исследование при отставании. Следите за городами, отношениями и шкалой активного проекта победы на вкладках мира и победы.", "ии искусственный интеллект соперник стратегия сложность характер цель объяснение очки"),
            new GuideArticle("pace", "Настройки кампании", "Темп и длительность партии", "Выберите продолжительность, которая подходит вашей сессии.",
                "Темп задаётся перед новой кампанией и сохраняется вместе с ней. «Спокойный» режим длится до 120 ходов; общие кризисы возникают реже, поэтому есть больше времени на освоение и развитие. «Стандартный» сохраняет привычный предел в 80 ходов. «Быстрый» рассчитан на 60 ходов и ускоряет ритм мировых кризисов.\n\n" +
                "Доход, стоимость зданий, сила войск и правила последствий не меняются. В быстром режиме меньше ходов на долгие проекты и восстановление, поэтому заранее выбирайте приоритет. Выбор темпа влияет на новый запуск; загруженная кампания продолжает использовать тот темп, с которым была создана.", "темп скорость длительность спокойный стандартный быстрый 120 80 60 партия"),
            new GuideArticle("difficulty", "Настройки кампании", "Сложность и темп — разные настройки", "Сложность меняет силу соперников, а темп — длину кампании.",
                "Сложность задаёт экономическую поддержку и настойчивость искусственного интеллекта. Спокойный уровень снижает выпуск соперников и даёт им шанс догонять науку; высокий уровень повышает выпуск и скорость исследования. На двух верхних уровнях соперники получают ещё и дополнительную стартовую административную ёмкость, а их характеры ведут разные планы победы. Вы можете выбрать сложность, не меняя темп.\n\n" +
                "Темп выбирается отдельно и меняет число ходов и интервал мировых кризисов. Например, длинную спокойную кампанию можно начать с сильными соперниками, если хочется неспешно изучать игру, но сохранить вызов. Параметры фиксируются для новой партии.", "сложность настройки темп ai соперник баланс"),
            new GuideArticle("chronicle", "Мир и события", "Летопись и отчёт хода", "Летопись помогает восстановить цепочку причин и последствий.",
                "После завершения хода откройте вкладку «Летопись». В отчёте собраны изменения ресурсов, населения, события, решения, соглашения и сражения. Последние записи находятся вверху, а итоговые показатели доступны в соответствующих вкладках.\n\n" +
                "Чтобы понять, почему город потерял выпуск, найдите запись о голоде, осаде, повреждении или миграции, затем сравните карточку города с прогнозом. В энциклопедии можно открыть статью по теме. Если сообщение непонятно, перед завершением хода проверьте подсказку на текущей вкладке.", "летопись история отчёт ход сообщение журнал"),
            new GuideArticle("resources", "Экономика", "Еда, казна, знания и влияние", "Общие ресурсы решают разные задачи и конкурируют за внимание.",
                "Еда принадлежит отдельным городам и кормит их жителей. Казна оплачивает содержание, строительство и некоторые ответы на события. Знания открывают технологии; потраченные на исследование знания превращаются в прогресс конкретного открытия. Влияние нужно для реформ, некоторых договоров, перехода эпохи и проектов победы.\n\n" +
                "Культурный престиж и культурное влияние — отдельные показатели: престиж показывает накопленное развитие культуры, а влияние оценивает отношения с каждым соседом. Не тратьте весь запас сразу: события, совместные проекты и внезапная война могут потребовать резерва. Вкладки города, науки и дипломатии показывают текущий прогноз и цену доступных действий.", "ресурсы еда казна деньги знания влияние культура престиж"),
            new GuideArticle("buildings", "Экономика", "Здания и их содержание", "Постройка помогает только тогда, когда закрывает потребность города.",
                "Здания дают жильё, склады, места для работников, знания, торговлю, культуру, безопасность или административную ёмкость. Почти каждое здание требует технологии и производства, а многие требуют казну каждый ход. Каталог доступных построек показывает условия открытия и цену.\n\n" +
                "После смены эпохи архитектурный вид города обновляется; само здание сохраняет функцию. Уникальные институты нельзя бесконечно дублировать. Постройка без назначенных специалистов может давать только часть ожидаемого эффекта. Проверьте городскую карточку и назначьте профильных работников, если хотите получить полный выпуск.", "здание постройка содержание жильё склад место работника архитектура казармы амбар"),
            new GuideArticle("map-units", "Мир", "Карта, разведка и отряды", "Карта показывает клетки, города, пути и только известные вам силы.",
                "Мир состоит из гексов разного рельефа. Клетка может быть под контролем цивилизации, содержать улучшение или нести повреждение. Карта не показывает неразведанные области и скрытые перемещения соперника. Нажмите на клетку, чтобы посмотреть доступные действия и условия строительства.\n\n" +
                "Отряды и обозы перемещаются по соседним гексам в пределах запаса движения. Горы и вода блокируют обычный проход; дороги и договор об открытых границах помогают планировать маршрут. Клетка рядом с городом влияет на положение сил, снабжение и оборону. Движение не означает автоматически начало боя: конфликт и боевой приказ требуют отдельных действий.", "карта гекс разведка клетка отряд движение обоз граница дорога рельеф"),
            new GuideArticle("achievements", "Настройки кампании", "Достижения, слава и титулы", "Постоянные награды отмечают стиль игры и не меняют баланс кампании.",
                "Достижения открываются за развитие городов, решения кризисов, дипломатию и завершение путей к победе. Они сохраняются между кампаниями вместе со славой профиля. Открытый титул можно надеть в меню профиля. Награда косметическая и не даёт дополнительных ресурсов, военной силы или бонуса к выпуску.\n\n" +
                "Карточка достижения показывает условия и текущий прогресс; часть целей завершается только в подходящей кампании. Если условие связано с городом или кризисом, откройте соответствующую статью энциклопедии, чтобы понять основное правило.", "достижение слава награда титул профиль косметический"),
            new GuideArticle("nations", "Нации и районы", "Древние цивилизации и их персонажи", "Стартовая база начинается с Иерихона, Шумера, Египта и долины Инда.",
                "У каждой цивилизации есть отдельный портрет, персонаж, города, игровой характер, постоянный бонус, учебный центр и уникальный район. Поселение Иерихон получает +10% еды; Шумер — +10% знаний; Египет — +10% культурного престижа; Индская цивилизация — +10% торгового дохода. Все пути к победе доступны всем четырём сторонам.\n\n" +
                "Хатшепсут — историческая правительница Египта, а Энхедуанна — исторически засвидетельствованная жрица и поэтесса, но не царица Шумера. Они жили в разные периоды и в кампании не считаются современниками. Для раннего Иерихона и долины Инда имена правителей неизвестны, поэтому их лидеры — явно обозначенные собирательные игровые образы. Учебные центры Иерихона и Инда также являются игровыми интерпретациями, а не доказанными древними университетами.", "нация цивилизация Иерихон Шумер Египет Хатшепсут Энхедуанна Инд портрет персонаж древность"),
            new GuideArticle("city-districts", "Нации и районы", "Центр города и районы", "Здания размещаются на отдельных клетках карты.",
                "Городской центр занимает один гекс, а каждое завершённое здание образует район на свободном гексе не дальше четырёх шагов от центра. Если клетка нейтральна, проект включает её в территорию при начале стройки; в карточке города видны координаты. Нажмите район, чтобы выбрать его город.\n\n" +
                "У каждой из четырёх стартовых цивилизаций есть собственный уникальный район: Башня источника, Зиккуратовый архив, Двор нилометра или Большая купальня. Район нельзя поставить на занятую или неподходящую клетку; участок резервируется до завершения стройки. Обычные здания меняют вид вместе с эпохой, а уникальные сохраняют форму культурного памятника.", "город район центр квартал здание карта гекс архитектура эпоха свободная клетка уникальный Иерихон Шумер Египет Инд"),
            new GuideArticle("culture-campuses", "Нации и районы", "Школы и университеты разных культур", "Одинаковая функция получает культурный архитектурный образ.",
                "Школа, университет и академия используют учебный образ выбранной цивилизации и небольшой культурный эффект. В Шумере Эдубба приносит +1 знание за ход, в Египте Пер-Анх — +1 образование, Круг памяти Иерихона — +1 культурный престиж, а Дом печати Инда — +1 казну за ход за каждый построенный учебный район.\n\n" +
                "Круг памяти и Дом печати обозначены как игровые реконструкции: мы не утверждаем, что у неолитического Иерихона была формальная школа или что у Индской цивилизации существовал известный университет. Уникальные городские районы дают отдельные эффекты и доступны только соответствующей цивилизации.", "университет школа академия культура Эдубба Пер-Анх Дом жизни Круг памяти Дом печати"),
            new GuideArticle("terrain-workers", "Город и люди", "Рельеф и специализация работников", "Работники автоматически выбирают подходящие клетки своего города.",
                "Назначение по роли задаёт работу жителя, а рельеф и улучшение клетки меняют её результат. Земледельцы выбирают клетки с наибольшим продовольственным эффектом: луг и река дают больше еды, засушливая земля и болото без подготовки уменьшают её, ферма и плодородная почва добавляют выпуск. Ирригационная ферма снимает засушливый штраф и даёт больший бонус.\n\n" +
                "Ремесленники получают дополнительное производство от леса, холмов, лесного хозяйства и мастерской. Игра распределяет жителей по самым продуктивным доступным клеткам автоматически, поэтому отдельное назначение каждого гекса не требуется. В карточке города проверьте общий прогноз перед сменой ролей.", "рельеф клетка работник земледелец фермер ремесленник луг лес холм река болото засушливая почва ферма мастерская"),
            new GuideArticle("mobile-map", "Начало", "Управление картой на телефоне", "Перемещайте карту, меняйте масштаб и быстро открывайте управление поселением.",
