        public static readonly string[] Categories = { "Все разделы", "Начало", "Экономика", "Город и люди", "Наука и эпохи", "Общество", "Дипломатия", "Мир и события", "Конфликты", "Победа", "Настройки кампании", "Нации и районы" };

        public static GuideArticle Find(string id)
        {
            if (string.IsNullOrEmpty(id)) return null;
            for (int i = 0; i < Entries.Length; i++) if (Entries[i].Id == id) return Entries[i];
            return null;
        }

        public static GuideArticle[] Search(string query, string category)
        {
            var results = new List<GuideArticle>();
            string term = (query ?? string.Empty).Trim();
            for (int i = 0; i < Entries.Length; i++)
            {
                GuideArticle article = Entries[i];
                if (!string.IsNullOrEmpty(category) && category != Categories[0] && article.Category != category) continue;
                if (term.Length > 0 && !Matches(article, term)) continue;
                results.Add(article);
            }
            return results.ToArray();
        }

        private static bool Matches(GuideArticle article, string query)
        {
            string searchable = article.Title + " " + article.Summary + " " + article.Body + " " + article.Keywords;
            string[] terms = query.Split(new[] { ' ', '\t', '\r', '\n', ',', '.', '?', '!', ';', ':', '«', '»' }, StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < terms.Length; i++)
                if (searchable.IndexOf(terms[i], StringComparison.OrdinalIgnoreCase) < 0) return false;
            return true;
        }
    }
